import{_ as t,o as a,c as r,ak as s}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse(`{"title":"Chainy technical design","description":"Adopted October 12, 2026 from Christian Jude Villaber's supplied design. The user identifies it as written and verified by the Tech Lead. This reference summarizes that design","frontmatter":{"title":"Chainy technical design","description":"Adopted October 12, 2026 from Christian Jude Villaber's supplied design. The user identifies it as written and verified by the Tech Lead. This reference summarizes that design","source":"docs/technical-design.md","category":"Game & system design","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/technical-design.md","filePath":"content/docs/technical-design.md"}`),n={name:"content/docs/technical-design.md"};function i(d,e,o,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[s(`<div><h1 id="chainy-technical-design">Chainy technical design<a class="header-anchor" href="#chainy-technical-design" aria-label="Link to this section">​</a></h1><p>Adopted October 12, 2026 from <a href="/Chainy-Docs/content/docs/archive/source-material/technical-design-christian-2026-10-12.html">Christian Jude Villaber&#39;s supplied design</a>. The user identifies it as written and verified by the Tech Lead. This reference summarizes that design; open inconsistencies are listed explicitly.</p><h2 id="how-the-game-is-organized">How the game is organized<a class="header-anchor" href="#how-the-game-is-organized" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Layer</th><th>Plain-language purpose</th><th>Components</th></tr></thead><tbody><tr><td>Presentation</td><td>Show the game and capture player actions</td><td>UI, input devices, UI Manager</td></tr><tr><td>Game logic</td><td>Decide what an action means and run the current activity</td><td>Input Manager, Game Manager, Quiz/Wordle/BlockMatch Managers, Level Manager, SceneLoader, Progress Manager</td></tr><tr><td>Data</td><td>Save and retrieve local records</td><td>Database Manager, SQLite</td></tr></tbody></table><p>The Event Bus carries commands and notifications between components. The Service Locator supplies registered services. UI Manager listens to events and is explicitly excluded from Service Locator registration. Game Manager activates only one mini-game at a time.</p><figure class="diagram"><div class="mermaid-source"><pre>flowchart TD
  P[Player touch or controls] --&gt; I[Input Manager]
  I --&gt; E[Event Bus]
  E --&gt; G[Game Manager]
  G --&gt; L[Level Manager and SceneLoader]
  G --&gt; M[Active Quiz, Wordle or BlockMatch]
  M --&gt; E
  E --&gt; U[UI Manager]
  U --&gt; V[Screens and feedback]
  E --&gt; R[Progress Manager]
  L --&gt; R
  R --&gt; D[Database Manager]
  D --&gt; DB[(Local SQLite)]
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><p>This is a simplified responsibility diagram. The source&#39;s <a href="/Chainy-Docs/attachments/docs/media/technical-design/image1.png">full diagram</a> also includes Dialogue Manager and object pooling.</p><h2 id="component-responsibilities">Component responsibilities<a class="header-anchor" href="#component-responsibilities" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Component</th><th>Owns</th><th>Important boundary</th></tr></thead><tbody><tr><td>Input Manager</td><td>Convert raw touch/pointer/keyboard input into game commands</td><td>Ignore input that is invalid during load, pause, save or board resolution</td></tr><tr><td>Event Bus</td><td>Route commands and notifications</td><td>Subscribers must not remain active after their scene/session ends</td></tr><tr><td>Game Manager</td><td>App state, session lifecycle, start/pause/resume/exit, active mini-game</td><td>Route gameplay to one mode only</td></tr><tr><td>UI Manager</td><td>Screens, HUD and feedback from events</td><td>No SQL; not registered in Service Locator</td></tr><tr><td>Level Manager</td><td>Level content, difficulty, objectives and configuration</td><td>Data comes through Progress Manager in the source architecture</td></tr><tr><td>SceneLoader</td><td>Load/unload scenes and report success/failure</td><td>Game Manager waits for readiness before starting play</td></tr><tr><td>Quiz Manager</td><td>Questions, answer evaluation and scoring</td><td>Return a result for persistence</td></tr><tr><td>Wordle Manager</td><td>Guess validation, letter evaluation and outcome</td><td>Follow the agreed dictionary and repeated-letter rules</td></tr><tr><td>BlockMatch Manager</td><td>Board moves, matches, cascades and objectives</td><td>Finish board resolution before accepting another move</td></tr><tr><td>Object Pooling</td><td>Reuse objects and effects</td><td>Reset objects when returned/reused</td></tr><tr><td>Progress Manager</td><td>Progress, unlocks, checkpoints and read/write coordination</td><td>Request storage operations and report their outcome</td></tr><tr><td>Database Manager</td><td>Parameterized SQL, transactions and schema changes</td><td>Central storage access; returns data or an explicit error</td></tr><tr><td>SQLite</td><td>Local content and learner records</td><td>No automatic cloud synchronization</td></tr><tr><td>Service Locator</td><td>Register and resolve service dependencies</td><td>Validate required services during startup</td></tr><tr><td>Dialogue Manager</td><td>Learning dialogue/interactions shown in the source diagram</td><td>Exact responsibility/API is absent from Part II; Christian must reconcile it</td></tr></tbody></table><p>Do not create replacement manager frameworks to match the old generated design. Work with the actual project structure and the Tech Lead&#39;s existing scripts.</p><h2 id="load-and-save-flows">Load and save flows<a class="header-anchor" href="#load-and-save-flows" aria-label="Link to this section">​</a></h2><p><strong>Load:</strong> profile input → Progress Manager → Database Manager → SQLite → Progress Manager → interested systems and UI. Activate the selected learner only after the read succeeds. A missing profile and a database error must lead to different messages.</p><p><strong>Save:</strong> active mini-game produces a result → Game Manager handles session state → Progress Manager requests a save → Database Manager writes it → Progress Manager reports success/failure → UI shows the outcome.</p><p>Recommended reliability rule: save related result/progress changes together; a retry must not count the same completion twice. The exact identifier and transaction are Christian&#39;s CH-04 decision. A save failure must leave the last successful save available.</p><p><strong>Return or switch learner:</strong> finish or resolve the current pending save, stop the active mode and clear its UI/state before loading the next profile. <strong>Pause/relaunch:</strong> resume a supported saved point; do not promise exact mid-animation or mid-cascade restoration. See the <a href="/Chainy-Docs/content/docs/design/app-flow.html">flow reference</a>.</p><h2 id="source-reconciliation-required">Source reconciliation required<a class="header-anchor" href="#source-reconciliation-required" aria-label="Link to this section">​</a></h2><p>These are small corrections for Christian, not grounds for discarding his architecture.</p><table><thead><tr><th>Source mismatch</th><th>Proposed resolution</th><th>Task</th></tr></thead><tbody><tr><td>Part IV adds Score Manager; Part II assigns scoring to Quiz Manager</td><td>Keep scoring in the active mode unless Christian confirms an existing shared Score Manager and its interface</td><td>CH-02/04</td></tr><tr><td>Part IV says Progress Manager generates SQL and one load step goes directly to the database; Parts I–II give SQL to Database Manager</td><td>Use Progress Manager for requests and Database Manager for SQL, following Parts I–II</td><td>CH-04</td></tr><tr><td>Dialogue Manager appears in the diagram and milestones but not the responsibility table</td><td>Record the existing dialogue component and how it starts/finishes an activity</td><td>CH-05</td></tr><tr><td>Architecture says content is in SQLite; current quiz reads ScriptableObjects</td><td>Document whether ScriptableObjects seed SQLite or remain the authoritative packaged quiz source; avoid two editable copies</td><td>CH-04/06</td></tr><tr><td>Sessions/checkpoints are promised but absent from the five-entity dictionary</td><td>Obtain the actual schema and define the smallest fields needed for supported resume and evaluation</td><td>CH-04</td></tr><tr><td>Source names Unity Cloud, while repository documents link Chainy-Game</td><td>Confirm the build source and revision; do not duplicate or migrate source by assumption</td><td>CH-03</td></tr></tbody></table><h2 id="data-and-implementation-status">Data and implementation status<a class="header-anchor" href="#data-and-implementation-status" aria-label="Link to this section">​</a></h2><p>The <a href="/Chainy-Docs/content/docs/design/database-schema.html">database reference</a> adopts User, Module, Lesson, User_Progress and User_Analytics as the source model. It preserves uncertain field names and data meanings as questions. No new runnable schema or migration is implied.</p><p>Part VI reports SQLite, profile, Quiz, UI and models in progress; player movement completed; Wordle and BlockMatch not started. The evidence named is summarized in the <a href="/Chainy-Docs/content/docs/project-baseline.html#current-implementation-evidence">baseline</a>. Source file names are reported evidence, not files inspected in this repository.</p><h2 id="existing-project-locations">Existing project locations<a class="header-anchor" href="#existing-project-locations" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Area</th><th>Location reported in source</th></tr></thead><tbody><tr><td>Scripts</td><td>Assets/Scripts/</td></tr><tr><td>Player controller</td><td>Assets/Scripts/Feature/PlayerSystem</td></tr><tr><td>Dialogue plugin</td><td>Assets/Plugins/</td></tr><tr><td>UI</td><td>Assets/UI</td></tr><tr><td>Scenes</td><td>Assets/Scenes</td></tr><tr><td>SceneLoader</td><td>Assets/Scripts/Core/SceneloaderSystem</td></tr><tr><td>Database</td><td>Assets/Scripts/Feature/Database System</td></tr></tbody></table><p>The folder screenshot shows “Features” while the table uses “Feature.” Preserve the actual paths in the game project; Christian should confirm spelling before task handoff. Do not reorganize working source solely to match a document.</p><h2 id="next-technical-handoff">Next technical handoff<a class="header-anchor" href="#next-technical-handoff" aria-label="Link to this section">​</a></h2><p>Christian supplies the actual schema, build source/revision and a working Quiz → save → reload demonstration. Miguel tests two profiles and failed-save feedback; Sean checks the meaning of stored results. This closes the most important uncertainty before Wordle and BlockMatch share the same flow.</p><p><strong>Fixed beta: November 3–6. Pre-final: November 21, 2026.</strong> Detailed scheduling is in the <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">task plan</a>.</p></div>`,1)])])}const p=t(n,[["render",i]]);export{u as __pageData,p as default};
